cd /app/submission && python3 - <<'EOF'
import json, sys
sys.path.insert(0, "/app/submission")
import importlib.util
spec = importlib.util.spec_from_file_location("entry", "/app/submission/entry.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
raw = open("/app/tmp/mem.json","rb").read()
doc = m._parse(raw)
# instrument validation
n_events = n_packets = n_frames = n_data = 0
for tr in doc["traces"]:
    n_events += len(tr["events"])
    for ev in tr["events"]:
        if ev["op"] == "datagram":
            n_packets += len(ev["packets"])
            for p in ev["packets"]:
                n_frames += len(p["frames"])
                for fr in p["frames"]:
                    if fr["type"] in ("CRYPTO","STREAM"):
                        n_data += len(fr["data_hex"])//2
print("events", n_events, "packets", n_packets, "frames", n_frames, "data", n_data)
try:
    m._validate(doc)
    print("VALID")
except m.Invalid as e:
    print("INVALID")
    # find the culprit by bisection
    import copy
    tr = doc["traces"][0]
    lo, hi = 0, len(tr["events"])
    # check config separately
    try:
        m._validate_config(tr["config"]); print("config ok")
    except m.Invalid: print("config BAD")
    for i, ev in enumerate(tr["events"]):
        d2 = {"version":1,"traces":[{"id":"t","config":tr["config"],"events":[ev]}]}
        try: m._validate(d2)
        except m.Invalid as e2: print("bad event", i, json.dumps(ev)[:300]); break
EOF
